#!/bin/bash
# check that the names generated by "btrfs-image -s" are made of printable
# characters, namely there are no zero bytes and no control characters

source "$TEST_TOP/common" || exit

check_prereq mkfs.btrfs
check_prereq btrfs
check_prereq btrfs-image

tmp=$(_mktemp_dir image-sanitize-names)
nr_files=200

mkdir "$tmp/src"
for i in $(seq -f '%04g' 1 $nr_files); do
	# With a single -s the names are always replaced by random garbage, the
	# crc collisions are searched for only with -ss. The name length (30) is
	# used below to pick the INODE_REF lines of these files.
	: > "$tmp/src/name_for_the_garbage_test_$i"
done

truncate -s 128M "$tmp/fs.img"
run_check "$TOP/mkfs.btrfs" -f --rootdir "$tmp/src" "$tmp/fs.img"
run_check "$TOP/btrfs-image" -s "$tmp/fs.img" "$tmp/fs.dump"
run_check "$TOP/btrfs-image" -r "$tmp/fs.dump" "$tmp/restored.img"
run_check_stdout "$TOP/btrfs" inspect-internal dump-tree -t 5 "$tmp/restored.img" > "$tmp/tree.txt"

# dump-tree prints the bytes that are not printable as an escape sequence, a
# backslash followed by a character other than a backslash
result=$(awk '
	/namelen 30 name: / {
		s = $0
		sub(/^.*name: /, "", s)
		names++
		for (i = 1; i <= length(s); i++) {
			if (substr(s, i, 1) == "\\") {
				if (substr(s, i + 1, 1) != "\\") {
					bad++
					break
				}
				i++
			}
		}
	}
	END { print names + 0, bad + 0 }' "$tmp/tree.txt")
names=${result% *}
bad=${result#* }

if [ "$names" -lt "$nr_files" ]; then
	_fail "test setup: found only $names sanitized names of $nr_files"
fi
if [ "$bad" -ne 0 ]; then
	_fail "$bad of $names sanitized names contain non-printable characters"
fi

rm -rf -- "$tmp"
